    /// `search_bounded(cap)` must return EXACTLY the same top-`cap` hits (same
    /// order, same scores) as the legacy `execute() + sort_unstable() +
    /// truncate(cap)`, and its reported `total` must equal the full match count
    /// regardless of `cap`.  Exercises both the streaming leaf-`Term` path and
    /// the `execute()`-then-drain compound (`Bool`) path.
    #[test]
    fn search_bounded_matches_legacy_topk_and_total() {
        let dir = TempDir::new().unwrap();
        let searcher = setup_searcher(dir.path());

        // Two query shapes with a MULTI-score match set:
        //  - Term "fox": docs 0,1,4 with distinct BM25 (doc 4 TF=4 ranks top).
        //  - Bool should(fox|quick|lazy): a wider, differently-scored set that
        //    routes through execute()-then-drain, not the streaming leaf.
        let term_q = Query::Term(TermQuery::new("body", "fox"));
        let bool_q = Query::Bool(Box::new(
            BoolQuery::new()
                .should(Query::Term(TermQuery::new("body", "fox")))
                .should(Query::Term(TermQuery::new("body", "quick")))
                .should(Query::Term(TermQuery::new("body", "lazy"))),
        ));

        for q in [&term_q, &bool_q] {
            // Legacy reference: usize::MAX keeps the full-set sort path.
            let full = searcher.search(q, usize::MAX, false).unwrap();
            let total_full = full.len() as u64;
            assert!(total_full >= 3, "query should match several docs");

            // Order must already be strictly non-increasing by score.
            for w in full.windows(2) {
                assert!(w[0].score >= w[1].score);
            }

            for cap in [
                0usize,
                1,
                2,
                3,
                total_full as usize,
                total_full as usize + 5,
            ] {
                let (bounded, total) = searcher.search_bounded(q, cap, false).unwrap();

                // (1) Exact total is independent of the page cap.
                assert_eq!(
                    total, total_full,
                    "bounded total must equal full match count at cap={cap}"
                );

                // (2) Top-`cap` is byte-identical to legacy sort+truncate.
                let expected: Vec<(u32, u32)> = full
                    .iter()
                    .take(cap)
                    .map(|h| (h.doc_id, h.score.to_bits()))
                    .collect();
                let got: Vec<(u32, u32)> = bounded
                    .iter()
                    .map(|h| (h.doc_id, h.score.to_bits()))
                    .collect();
                assert_eq!(
                    got, expected,
                    "bounded top-{cap} must match legacy sort+truncate (doc_id+score)"
                );
            }
        }
    }

    /// Corpus sized to make the WAND bound actually bite: one term in every
    /// document (low idf → a tiny score upper bound) beside one term in three
    /// documents (high idf → the only scores that can fill a page).
    ///
    /// Returns the searcher.
    fn wand_fixture(dir: &std::path::Path) -> FtsSearcher {
        let registry = Arc::new(AnalyzerRegistry::default());
        let mut writer = FtsIndexWriter::new(dir, "seg0", Arc::clone(&registry));
        writer.configure_field(
            "body",
            FieldIndexConfig {
                analyzer: "whitespace".to_owned(),
                ..Default::default()
            },
        );
        for i in 0..300u32 {
            // Docs 0..3 carry "needle"; every doc carries "the". Lengths vary
            // so `field_length` lookups differ across the walk.
            let text = if i < 3 {
                format!("the needle pad{i}")
            } else {
                format!("the pad{i} filler{}", i % 7)
            };
            let fields: HashMap<String, FieldValues> =
                [("body".to_owned(), FieldValues::from(text))]
                    .into_iter()
                    .collect();
            writer.add_document(i, &fields);
        }
        writer.finish().unwrap();
        let reader = Arc::new(FtsIndexReader::open(dir, "seg0", &["body"]).unwrap());
        FtsSearcher::new(reader, registry)
    }

    /// The WAND path (`search_bounded` on a should-only bool of terms) must be
    /// indistinguishable from the generic path — same hits, same order,
    /// **bit-identical scores**, same exact total — on a corpus where the
    /// pruning branch genuinely fires, and it must fire by construction, not
    /// by luck.
    ///
    /// The pruning precondition is ASSERTED, not assumed (the lesson of
    /// `bool_deadline_never_broadens_a_must_not`): once the page holds the
    /// three needle docs, a "the"-only doc can enter only if
    /// `idf(the)·(k1+1) ≥ worst-retained-score` — and this test fails loudly
    /// if that ever stops holding, because then the 297 pruning decisions it
    /// relies on would not have happened and the equivalence above would be
    /// passing vacuously over the same docs the legacy test already covers.
    #[test]
    fn wand_should_bool_matches_generic_path_when_pruning_fires() {
        let dir = TempDir::new().unwrap();
        let searcher = wand_fixture(dir.path());

        let q = Query::Bool(Box::new(
            BoolQuery::new()
                .should(Query::Term(TermQuery::new("body", "the")))
                .should(Query::Term(TermQuery::new("body", "needle"))),
        ));

        // Reference: usize::MAX never takes the WAND path, so this is the
        // generic walk's answer in full.
        let full = searcher.search(&q, usize::MAX, false).unwrap();
        assert_eq!(full.len(), 300, "every doc matches 'the'");
        for w in full.windows(2) {
            assert!(w[0].score >= w[1].score);
        }

        // --- the non-vacuity precondition ---
        // The three needle docs must be the page at cap=3, and the common
        // term's score supremum must sit strictly below that page's worst —
        // exactly the comparison the walk makes for each of the 297
        // "the"-only docs.
        assert_eq!(
            full[..3].iter().map(|h| h.doc_id).collect::<Vec<_>>(),
            vec![0, 1, 2],
            "the three needle docs must lead the ranking"
        );
        let bm25 = searcher.make_scorer("body");
        let the_df = searcher.scoring_df("body", "the", 300);
        let the_ubound = bm25.idf(the_df) * (bm25.k1 + 1.0);
        assert!(
            the_ubound < full[2].score,
            "precondition: 'the'-only docs (bound {the_ubound:.4}) must be prunable \
             against the cap-3 page (worst {:.4}) — otherwise this test exercises \
             no pruning",
            full[2].score
        );

        for cap in [0usize, 1, 2, 3, 5, 300, 305] {
            let (bounded, total) = searcher.search_bounded(&q, cap, false).unwrap();
            assert_eq!(total, 300, "exact total must survive pruning at cap={cap}");
            let expected: Vec<(u32, u32)> = full
                .iter()
                .take(cap)
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect();
            let got: Vec<(u32, u32)> = bounded
                .iter()
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect();
            assert_eq!(
                got, expected,
                "WAND top-{cap} must be byte-identical to the generic path"
            );
        }
    }

    /// Clause shapes that must NOT take the WAND path (`min_should_match > 1`,
    /// `must` beside `should`, a non-`Term` should clause) still get correct
    /// bounded answers — the shape guard falls them through to the generic
    /// walk, and this pins that the fallthrough, not just the guard, is right.
    #[test]
    fn wand_should_bool_falls_back_for_richer_shapes() {
        let dir = TempDir::new().unwrap();
        let searcher = wand_fixture(dir.path());

        let shapes: Vec<(&str, Query)> = vec![
            (
                "min_should_match=2",
                Query::Bool(Box::new(
                    BoolQuery::new()
                        .should(Query::Term(TermQuery::new("body", "the")))
                        .should(Query::Term(TermQuery::new("body", "needle")))
                        .min_should_match(2),
                )),
            ),
            (
                "must + should",
                Query::Bool(Box::new(
                    BoolQuery::new()
                        .must(Query::Term(TermQuery::new("body", "needle")))
                        .should(Query::Term(TermQuery::new("body", "the"))),
                )),
            ),
            (
                "non-Term should clause",
                Query::Bool(Box::new(
                    BoolQuery::new()
                        .should(Query::Term(TermQuery::new("body", "the")))
                        .should(Query::Prefix(PrefixQuery::new("body", "needl"))),
                )),
            ),
        ];

        for (name, q) in &shapes {
            let full = searcher.search(q, usize::MAX, false).unwrap();
            assert!(!full.is_empty(), "{name}: fixture must match something");
            for cap in [0usize, 1, 2, 3, 10, full.len(), full.len() + 5] {
                let (bounded, total) = searcher.search_bounded(q, cap, false).unwrap();
                assert_eq!(total, full.len() as u64, "{name}: total at cap={cap}");
                let expected: Vec<(u32, u32)> = full
                    .iter()
                    .take(cap)
                    .map(|h| (h.doc_id, h.score.to_bits()))
                    .collect();
                let got: Vec<(u32, u32)> = bounded
                    .iter()
                    .map(|h| (h.doc_id, h.score.to_bits()))
                    .collect();
                assert_eq!(got, expected, "{name}: top-{cap}");
            }
        }
    }

    /// The WAND path's own clause bookkeeping on the awkward-but-legal edges:
    /// a DUPLICATE term (two cursors over the same postings, both must land in
    /// the clause-order sum), a boosted term (the bound must carry the boost
    /// or pruning would over-prune), an absent term (dropped like the generic
    /// path's empty per-clause vec), and a bool-level boost (applied exactly
    /// where the generic path applies it).
    #[test]
    fn wand_should_bool_duplicate_boosted_absent_and_bool_boost() {
        let dir = TempDir::new().unwrap();
        let searcher = wand_fixture(dir.path());

        let mut tq_dup = TermQuery::new("body", "needle");
        tq_dup.boost = 2.0;
        let q = Query::Bool(Box::new(
            BoolQuery::new()
                .should(Query::Term(tq_dup))
                // duplicate clause over the same postings, default boost
                .should(Query::Term(TermQuery::new("body", "needle")))
                .should(Query::Term(TermQuery::new("body", "the")))
                // absent from every doc
                .should(Query::Term(TermQuery::new("body", "absentterm")))
                .boost(1.5),
        ));

        let full = searcher.search(&q, usize::MAX, false).unwrap();
        assert_eq!(full.len(), 300, "the still matches everything");
        // The duplicate must actually double-count: each needle doc's score
        // here exceeds the same doc's single-needle score by roughly the
        // single contribution (boost 2.0 + 1.0 = 3× vs 1×).
        let single = Query::Bool(Box::new(
            BoolQuery::new().should(Query::Term(TermQuery::new("body", "needle"))),
        ));
        let single_hits = searcher.search(&single, usize::MAX, false).unwrap();
        let s0 = single_hits.iter().find(|h| h.doc_id == 0).unwrap().score;
        let d0 = full.iter().find(|h| h.doc_id == 0).unwrap().score;
        assert!(
            d0 > s0 * 4.0,
            "duplicate + 2.0 boost + 1.5 bool boost must compound: {d0:.4} vs {s0:.4}"
        );

        for cap in [0usize, 1, 2, 3, 7, 300] {
            let (bounded, total) = searcher.search_bounded(&q, cap, false).unwrap();
            assert_eq!(total, 300, "total at cap={cap}");
            let expected: Vec<(u32, u32)> = full
                .iter()
                .take(cap)
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect();
            let got: Vec<(u32, u32)> = bounded
                .iter()
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect();
            assert_eq!(
                got, expected,
                "top-{cap} with duplicate/boosted/absent clauses"
            );
        }
    }

    /// Micro-bench (ignored by default; run with `--ignored`): the WAND path
    /// vs the generic bounded walk on a stopword-heavy disjunction over a
    /// 200k-doc synthetic index — the shape that motivated the fast path.
    /// `WAND_BENCH="clauses,cap"` (default "3,10") selects the clause count
    /// and page size; `WAND_BENCH="1,0"` measures the pure walk (nothing ever
    /// scored).  Asserts result equivalence once so the timing cannot silently
    /// drift onto unequal answers.
    #[test]
    #[ignore]
    fn bench_wand_vs_generic_stopword_disjunction() {
        let cfg = std::env::var("WAND_BENCH").unwrap_or_else(|_| "3,10".to_owned());
        let (nclauses, cap): (usize, usize) = {
            let mut it = cfg.split(',');
            (
                it.next().unwrap_or("3").parse().unwrap(),
                it.next().unwrap_or("10").parse().unwrap(),
            )
        };
        let dir = tempfile::TempDir::new().unwrap();
        let registry = Arc::new(AnalyzerRegistry::default());
        let mut writer = FtsIndexWriter::new(dir.path(), "seg0", Arc::clone(&registry));
        writer.configure_field(
            "body",
            FieldIndexConfig {
                analyzer: "whitespace".to_owned(),
                ..Default::default()
            },
        );
        const N: u32 = 200_000;
        let stops = ["the", "of", "and", "to", "in", "is"];
        for i in 0..N {
            // Terms of full df (the "stopwords"), a graded mid-df term, and
            // unique padding for realistic lengths.
            let mid = if i % 4 == 0 { "mid" } else { "pad" };
            let text = format!(
                "{} {mid} u{i}",
                stops[..nclauses.min(stops.len())].join(" ")
            );
            let fields: HashMap<String, FieldValues> =
                [("body".to_owned(), FieldValues::from(text))]
                    .into_iter()
                    .collect();
            writer.add_document(i, &fields);
        }
        writer.finish().unwrap();
        let reader = Arc::new(FtsIndexReader::open(dir.path(), "seg0", &["body"]).unwrap());
        let searcher = FtsSearcher::new(reader, registry);

        let mut bq = BoolQuery::new();
        for t in &stops[..nclauses.min(stops.len())] {
            bq = bq.should(Query::Term(TermQuery::new("body", *t)));
        }
        let q = Query::Bool(Box::new(bq));
        const REPS: u32 = 20;
        let _ = searcher.search_bounded(&q, cap, false).unwrap(); // warm
        let mut wand_us = 0f64;
        for _ in 0..REPS {
            let t0 = std::time::Instant::now();
            let _ = searcher.search_bounded(&q, cap, false).unwrap();
            wand_us += t0.elapsed().as_secs_f64() * 1e6;
        }
        let (g_hits, g_total) = searcher
            .search_bounded_observed(&q, cap, false, |_| {})
            .unwrap();
        let mut gen_us = 0f64;
        for _ in 0..REPS {
            let t0 = std::time::Instant::now();
            let _ = searcher
                .search_bounded_observed(&q, cap, false, |_| {})
                .unwrap();
            gen_us += t0.elapsed().as_secs_f64() * 1e6;
        }
        let (w_hits, w_total) = searcher.search_bounded(&q, cap, false).unwrap();
        assert_eq!(w_total, g_total);
        assert_eq!(
            w_hits
                .iter()
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect::<Vec<_>>(),
            g_hits
                .iter()
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect::<Vec<_>>(),
        );
        println!(
            "{nclauses}-stopword disjunction over {N} docs (df={N} each), cap={cap}: \
             generic {gen_us:.0} µs vs WAND {wand_us:.0} µs ({:.1}×), total={w_total}",
            gen_us / wand_us
        );
    }
}

//! Byte-backed raw segment reader experiments.
//!
//! This module is intentionally narrow. It supports one local, numeric-term,
//! `u32`-weighted raw segment format so query code can read posting lists
//! without reconstructing a full [`crate::PostingsIndex`].

use crate::codec::varint;
use crate::{CandidatePlan, DocId, PlannerConfig, PostingsIndex};
use std::collections::{btree_map::Entry, BTreeMap, HashMap};
use std::fs::File;
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::Path;

const MAGIC: &[u8; 8] = b"PSTRW001";
const FOOTER_MAGIC: &[u8; 8] = b"PSTRF001";
/// Current format. Version 4 adds a CRC32 of the 72-byte header to the
/// integrity section, since the header holds the checksum flag, the offsets,
/// and the length totals that no section CRC covers.
const VERSION: u32 = 4;
/// Last version without a header CRC. Still readable; a bit flip in the
/// header of such a segment can go undetected.
const VERSION_WITHOUT_HEADER_CRC: u32 = 3;
const HEADER_LEN: usize = 72;
const TERM_ENTRY_LEN: usize = 48;
const DOC_ENTRY_LEN: usize = 8;
const BLOCK_ENTRY_LEN: usize = 24;
const FOOTER_LEN: usize = 12;
const DEFAULT_BLOCK_SIZE: u32 = 128;
/// Header flag bit: the segment carries a content-integrity section (section
/// CRC32s + one CRC32 per posting block) between the postings region and the
/// footer. Readers that predate this flag reject it via `UnsupportedFlags`,
/// so they can never silently misread a checksummed segment.
const FLAG_CHECKSUMS: u32 = 1;
/// Fixed prefix of the integrity section: term-dir, doc-meta, block-dir, and
/// header CRC32s, in that order, followed by one CRC32 per block in directory
/// order. Version 3 segments have the same prefix without the header CRC.
const INTEGRITY_HEADER_LEN: usize = 16;
const INTEGRITY_HEADER_LEN_V3: usize = 12;
// Keep normal local-file queries on one read, but cap pathological high-DF term
// payloads so file-backed traversal cannot allocate an entire huge posting list.
const FILE_FULL_POSTINGS_READ_LIMIT: u64 = 1024 * 1024;

/// A numeric term id in the first raw postings format.
pub type RawTermId = u64;

type RawDocumentLengths = Vec<(DocId, u32)>;
type BorrowedRawTermPostings<'a> = Vec<(RawTermId, &'a [(DocId, u32)])>;

/// Segment-level diagnostics for multi-file raw sparse top-k search.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct RawTopKSearchStats {
    /// Raw segment files supplied to the search.
    pub segments_seen: usize,
    /// Raw segment files actually scored.
    pub segments_scored: usize,
    /// Raw segment files skipped by a zero bound or current top-k threshold.
    pub segments_pruned: usize,
}

/// Hits and segment-level diagnostics from multi-file raw sparse top-k search.
#[derive(Clone, Debug, PartialEq)]
pub struct RawTopKSearchResult {
    /// Top-k hits sorted by descending score, then document id.
    pub hits: Vec<(DocId, f32)>,
    /// Segment-pruning diagnostics for the search.
    pub stats: RawTopKSearchStats,
}

/// Errors returned by raw segment encoding and decoding.
#[derive(thiserror::Error, Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum Error {
    /// Segment bytes do not start with the expected magic.
    #[error("raw segment has invalid magic")]
    BadMagic,
    /// Segment footer is missing or does not match the expected magic.
    #[error("raw segment has invalid footer")]
    BadFooter,
    /// Segment version is newer or otherwise unsupported by this reader.
    #[error("unsupported raw segment version: {version}")]
    UnsupportedVersion {
        /// Version found in the segment header.
        version: u32,
    },
    /// Header flags contain bits this reader does not understand.
    #[error("unsupported raw segment flags: {flags:#x}")]
    UnsupportedFlags {
        /// Raw flag bits from the segment header.
        flags: u32,
    },
    /// Segment bytes ended before the named section could be read.
    #[error("truncated raw segment section: {section}")]
    Truncated {
        /// Section being decoded when truncation was found.
        section: &'static str,
    },
    /// Section offsets or lengths are inconsistent.
    #[error("invalid raw segment layout: {reason}")]
    InvalidLayout {
        /// Description of the violated layout invariant.
        reason: &'static str,
    },
    /// Stored content checksum did not match the recomputed value.
    #[error("raw segment checksum mismatch in {section}")]
    ChecksumMismatch {
        /// Section whose recomputed CRC32 disagreed with the stored one.
        section: &'static str,
    },
    /// Two documents in the input used the same id.
    #[error("duplicate raw segment doc id: {doc_id}")]
    DuplicateDocId {
        /// Duplicate document id.
        doc_id: DocId,
    },
    /// A sorted raw segment writer received a smaller document id after a
    /// larger one.
    #[error("raw segment doc ids must be increasing: previous {previous}, current {current}")]
    UnsortedDocId {
        /// Previous document id in the input stream.
        previous: DocId,
        /// Current document id that violated the ordering requirement.
        current: DocId,
    },
    /// A raw posting used a zero term weight.
    #[error("zero raw segment weight for doc {doc_id}, term {term_id}")]
    ZeroWeight {
        /// Document containing the zero weight.
        doc_id: DocId,
        /// Term with the zero weight.
        term_id: RawTermId,
    },
    /// Per-document weight accumulation overflowed `u32`.
    #[error("raw segment term weight overflow for doc {doc_id}, term {term_id}")]
    WeightOverflow {
        /// Document whose accumulated term weight overflowed.
        doc_id: DocId,
        /// Term whose accumulated weight overflowed.
        term_id: RawTermId,
    },
    /// Document length accumulation overflowed `u32`.
    #[error("raw segment document length overflow for doc {doc_id}")]
    DocLengthOverflow {
        /// Document whose length overflowed.
        doc_id: DocId,
    },
    /// A segment contains more documents than the format can encode.
    #[error("raw segment has too many documents")]
    TooManyDocuments,
    /// A segment contains more distinct terms than the format can encode.
    #[error("raw segment has too many terms")]
    TooManyTerms,
    /// A byte range cannot be represented on this platform.
    #[error("raw segment byte range is too large")]
    SegmentTooLarge,
    /// A posting list varint could not be decoded.
    #[error("invalid varint in raw postings for term {term_id} at posting {index}")]
    InvalidVarint {
        /// Term whose posting list is corrupt.
        term_id: RawTermId,
        /// Posting index within the term's posting list.
        index: u32,
    },
    /// A decoded posting list overflowed `DocId`.
    #[error("doc id overflow in raw postings for term {term_id} at posting {index}")]
    DocIdOverflow {
        /// Term whose posting list is corrupt.
        term_id: RawTermId,
        /// Posting index within the term's posting list.
        index: u32,
    },
    /// A decoded posting list did not stay strictly increasing.
    #[error("non-increasing doc id in raw postings for term {term_id} at posting {index}")]
    NonIncreasingDocId {
        /// Term whose posting list is corrupt.
        term_id: RawTermId,
        /// Posting index within the term's posting list.
        index: u32,
    },
    /// A posting list had bytes left after decoding its declared document count.
    #[error("trailing bytes in raw postings for term {term_id}")]
    TrailingPostingsBytes {
        /// Term whose posting list has trailing bytes.
        term_id: RawTermId,
    },
    /// Two term posting lists in the input used the same term id.
    ///
    /// New variants are appended to avoid changing the implicit discriminants
    /// observable through numeric casts on older variants.
    #[error("duplicate raw segment term id: {term_id}")]
    DuplicateTermId {
        /// Duplicate term id.
        term_id: RawTermId,
    },
    /// A term-major raw segment writer received a smaller term id after a
    /// larger one.
    #[error("raw segment term ids must be increasing: previous {previous}, current {current}")]
    UnsortedTermId {
        /// Previous term id in the input stream.
        previous: RawTermId,
        /// Current term id that violated the ordering requirement.
        current: RawTermId,
    },
    /// A term-major raw segment writer received a term with no postings.
    #[error("empty raw segment posting list for term {term_id}")]
    EmptyPostingList {
        /// Term with no postings.
        term_id: RawTermId,
    },
    /// A term-major raw segment writer received a posting for a document id
    /// missing from the document-length table.
    #[error("raw segment posting references unknown doc {doc_id} for term {term_id}")]
    UnknownDocId {
        /// Term containing the unknown document id.
        term_id: RawTermId,
        /// Posting document id missing from document metadata.
        doc_id: DocId,
    },
}

/// Errors returned when writing a raw segment to an external writer.
#[derive(thiserror::Error, Debug)]
#[non_exhaustive]
pub enum RawSegmentWriteError {
    /// Raw segment construction failed before bytes could be written.
    #[error(transparent)]
    Segment {
        /// Source raw segment error.
        source: Error,
    },
    /// Underlying writer I/O failed.
    #[error("raw segment writer I/O failed")]
    Io {
        /// Source I/O error.
        #[source]
        source: std::io::Error,
    },
}

impl From<std::io::Error> for RawSegmentWriteError {
    fn from(source: std::io::Error) -> Self {
        Self::Io { source }
    }
}

// Written out instead of `#[from]`: clippy 1.99 flags the `source: source`
// field init that thiserror's generated `From` impl contains.
impl From<Error> for RawSegmentWriteError {
    fn from(source: Error) -> Self {
        Self::Segment { source }
    }
}

/// Errors returned by file-backed raw segment readers.
#[derive(thiserror::Error, Debug)]
#[non_exhaustive]
pub enum RawSegmentFileError {
    /// Underlying file I/O failed.
    #[error("raw segment file I/O failed")]
    Io {
        /// Source I/O error.
        #[source]
        source: std::io::Error,
    },
    /// Raw segment bytes or metadata were invalid.
    #[error(transparent)]
    Segment {
        /// Source raw segment error.
        source: Error,
    },
}

impl From<std::io::Error> for RawSegmentFileError {
    fn from(source: std::io::Error) -> Self {
        Self::Io { source }
    }
}

// Written out instead of `#[from]`: clippy 1.99 flags the `source: source`
// field init that thiserror's generated `From` impl contains.
impl From<Error> for RawSegmentFileError {
    fn from(source: Error) -> Self {
        Self::Segment { source }
    }
}

/// A document accepted by the first raw segment writer.
///
/// Duplicate term ids are accumulated. The document length is the sum of all
/// supplied `u32` weights before duplicate-term accumulation.
#[derive(Debug, Clone, Copy)]
pub struct RawDocument<'a> {
    doc_id: DocId,
    terms: &'a [(RawTermId, u32)],
}

impl<'a> RawDocument<'a> {
    /// Create a raw document view.
    pub fn new(doc_id: DocId, terms: &'a [(RawTermId, u32)]) -> Self {
        Self { doc_id, terms }
    }

    /// Return the document id.
    pub fn doc_id(self) -> DocId {
        self.doc_id
    }

    /// Return the raw weighted terms.
    pub fn terms(self) -> &'a [(RawTermId, u32)] {
        self.terms
    }
}

/// A term-major posting list accepted by the raw segment writer.
///
/// Term ids must be strictly increasing across lists. Posting document ids must
/// be strictly increasing within a list and must exist in the document-length
/// table supplied to the term-major writer.
#[derive(Debug, Clone, Copy)]
pub struct RawTermPostingList<'a> {
    term_id: RawTermId,
    postings: &'a [(DocId, u32)],
}

impl<'a> RawTermPostingList<'a> {
    /// Create a raw term posting-list view.
    pub fn new(term_id: RawTermId, postings: &'a [(DocId, u32)]) -> Self {
        Self { term_id, postings }
    }

    /// Return the raw term id.
    pub fn term_id(self) -> RawTermId {
        self.term_id
    }

    /// Return the raw `(doc_id, weight)` postings.
    pub fn postings(self) -> &'a [(DocId, u32)] {
        self.postings
    }
}

/// Header metadata for a raw segment.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RawSegmentMeta {
    term_count: u32,
    doc_count: u32,
    max_doc_id: DocId,
    block_size: u32,
    total_doc_len: u64,
    term_dir_offset: u64,
    doc_meta_offset: u64,
    postings_offset: u64,
    footer_offset: u64,
    flags: u32,
    version: u32,
}

impl RawSegmentMeta {
    fn has_checksums(self) -> bool {
        self.flags & FLAG_CHECKSUMS != 0
    }

    fn has_header_crc(self) -> bool {
        self.version > VERSION_WITHOUT_HEADER_CRC
    }

    fn integrity_header_len(self) -> usize {
        if self.has_header_crc() {
            INTEGRITY_HEADER_LEN
        } else {
            INTEGRITY_HEADER_LEN_V3
        }
    }
}

impl RawSegmentMeta {
    /// Number of distinct terms in the segment.
    pub fn term_count(self) -> u32 {
        self.term_count
    }

    /// Number of documents in the segment.
    pub fn doc_count(self) -> u32 {
        self.doc_count
    }

    /// Highest document id in the segment, or zero for an empty segment.
    pub fn max_doc_id(self) -> DocId {
        self.max_doc_id
    }

    /// Target block size recorded for the segment.
    pub fn block_size(self) -> u32 {
        self.block_size
    }

    /// Sum of document lengths in the segment.
    pub fn total_doc_len(self) -> u64 {
        self.total_doc_len
    }

    /// Average document length.
    pub fn avg_doc_len(self) -> f32 {
        if self.doc_count == 0 {
            return 0.0;
        }
        self.total_doc_len as f32 / self.doc_count as f32
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TermEntry {
    term_id: RawTermId,
    df: u32,
    max_weight: u32,
    total_weight: u64,
    postings_offset: u64,
    postings_len: u32,
}

impl TermEntry {
    /// Capacity to reserve for this term's decoded postings.
    ///
    /// `df` comes from the file, so it cannot size an allocation on its own.
    /// Every posting is a doc-gap varint plus a weight varint, at least two
    /// bytes, so the postings bytes bound how many can really be there.
    fn posting_capacity(self) -> usize {
        (self.df as usize).min(self.postings_len as usize / 2)
    }
}

