                        max_candidate_ratio: 2.0,
                        max_candidates: 10,
                    },
                )
                .unwrap(),
            CandidatePlan::Candidates(vec![2, 5, 9])
        );
        assert_eq!(
            segment.resident_metadata_len(),
            expected_resident_metadata_len,
            "range reads must not promote posting payloads into resident metadata"
        );
    }

